        if isinstance(allowed_databases, str):
            allowed_databases = literal_eval(allowed_databases)

        if hasattr(g, "user"):
            extra_allowed_databases = app.config["ALLOWED_USER_CSV_SCHEMA_FUNC"](
                self, g.user
