        self,
        qry: Select,
        catalog: str | None = None,
        schema: str | None = None,
        is_virtual: bool = False,
    ) -> str:
        with self.get_sqla_engine(catalog=catalog, schema=schema) as engine:
            sql = str(qry.compile(engine, compile_kwargs={"literal_binds": True}))

