    def load_into_dataframe(
        self,
        description: DbapiDescription,
        data: list[tuple[Any, ...]],
    ) -> pd.DataFrame:
        result_set = SupersetResultSet(
            data,
            description,
            self.db_engine_spec,
        )
        return result_set.to_pandas_df()

